//		Exec(ctx)
func (_c *AICallCreateBulk) OnConflictColumns(columns ...string) *AICallUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &AICallUpsertBulk{
		create: _c,
	}
}

// AICallUpsertBulk is the builder for "upsert"-ing
